WFJ.Data.add("book", {
  ["0105829b41883dcf"] = { "Considerato un protettore, lo Stormo dei Draghi di Bronzo è molto attratto dalle zone civilizzate. Il drago e il suo stormo sono per natura molto pazienti: si affidano sempre all'osservazione e agiscono secondo un piano invece di essere avventati. Nozdormu cercherà sempre di proteggere il flusso del tempo e le razze mortali quando sono minacciati da nemici più grandi.", "." },
  ["010bacffd9d7ba09"] = { "Dopo molti lunghi anni, gli alti elfi trovarono finalmente una terra che ricordava Kalimdor. Nel cuore delle foreste settentrionali del continente fondarono il regno di Quel'Thalas e giurarono di creare un impero possente, che avrebbe fatto impallidire quello dei loro cugini Kaldorei. Purtroppo scoprirono presto che Quel'Thalas sorgeva su un'antica città troll che i troll ritenevano ancora sacra. Quasi subito, i troll cominciarono ad attaccare in massa gli insediamenti elfici.", "." },
  ["01210d98b7a2a2d3"] = { "Benché i suoi poteri fossero indeboliti dalla debolezza del Re dei Lich, Arthas era stato coinvolto in una guerra civile a Lordaeron. Metà delle forze non morte, guidate dalla banshee Sylvanas Windrunner, aveva tentato un colpo di stato per prendere il controllo dell'impero dei non morti. Chiamato dal Re dei Lich, Arthas fu costretto a lasciare il Flagello nelle mani del suo luogotenente, Kel'Thuzad, mentre la guerra divampava in tutte le ⟦Plaguelands=Terre Infette⟧.", "." },
  ["01461df9ceaadb92"] = { "⟦Vial of Phlogiston=Fiala di Flogisto⟧:\n\nL'ultima fase della creazione dell'armatura richiederà una forgia caldissima. Per produrre il calore necessario devo avere una fiala di flogisto.\n\nL'unico produttore conosciuto di questa sostanza è il leggendario verrospino Roogug, e non la cederà senza combattere. Roogug vive nelle profondità delle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧, nelle ⟦Barrens=Savane⟧ meridionali.", "." },
  ["015316f3053d4f27"] = { "Re Llane aveva gravemente sottovalutato la potenza dell'⟦Horde=Orda⟧, e assistette impotente alla caduta del suo regno per mano degli invasori dalla pelle verde. Alla fine re Llane fu assassinato da uno dei migliori sicari del Concilio dell'Ombra: la mezz'orca Garona.", "." },
})
